// B. Verifiable, one requirement per statement, no design decision, a defined response, consistent with R8.
const FIXES = {
  B1: {
    problem: 'UNVERIFIABLE',
    rewrite: 'The system shall display the estimated waiting time of a ticket within 2 seconds after the ticket is issued.',
  },
  B2: {
    problem: 'AMBIGUOUS',
    rewrite: 'The system shall send the call SMS to the mobile number registered for the patient; when the patient is under 16, it shall send it to the registered guardian instead.',
  },
  B3: {
    problem: 'COMPOUND',
    rewrite: [
      'The system shall let a doctor call the next waiting patient of the doctor’s room.',
      'The system shall let the clinic manager print the daily queue report.',
      'The system shall let the clinic manager export the monthly queue statistics as an .xlsx file.',
    ],
  },
  B4: {
    problem: 'DESIGN',
    rewrite: 'The system shall keep every issued queue number for 90 days and shall never issue the same number twice in one day.',
  },
  B5: {
    problem: 'INCOMPLETE',
    rewrite: 'If the patient does not reach the room within 3 minutes after the third call, the system shall mark the ticket as No-show and call the next waiting patient.',
  },
  B6: {
    problem: 'UNVERIFIABLE',
    rewrite: 'At least 90% of patients aged 65 or older shall obtain a ticket at the kiosk within 60 seconds without help, measured in the acceptance usability test.',
  },
  B7: {
    problem: 'INCONSISTENT',
    rewrite: 'When a doctor presses Call next, the system shall assign the waiting patient with the highest priority class (Emergency, then Priority, then Normal) and, within the same class, the earliest issue time.',
  },
  B8: {
    problem: 'INCOMPLETE',
    rewrite: 'The system shall be able to issue at least 3,000 tickets per day.',
  },
};

// C. External quality attributes of Wiegers Ch.14 (+ internal: modifiability, scalability…).
const ATTRIBUTES = {
  Q1: 'Availability',
  Q2: 'Security',
  Q3: 'Usability',
  Q4: 'Robustness',
  Q5: 'Interoperability',
  Q6: 'Scalability',
  Q7: 'Modifiability',
  Q8: 'Integrity',
};

// D. Each: attribute + shall + number + unit + condition, about MedQueue.
const NFRS = [
  { attribute: 'Performance', requirement: 'The hall screen shall show a newly called number within 2 seconds after the doctor presses Call next, in 95% of calls with 500 concurrent users.' },
  { attribute: 'Availability', requirement: 'The kiosks shall be able to issue tickets 99.9% of the time between 06:00 and 18:00 on working days, measured monthly.' },
  { attribute: 'Security', requirement: 'The system shall lock a staff account for 15 minutes after 5 consecutive failed sign-in attempts.' },
];

// E. Gilb's Planguage: a stopwatch can judge it.
const PLANGUAGE = {
  tag: 'Performance.CallDisplay',
  ambition: 'Patients see their number on the hall screen almost as soon as the doctor calls them.',
  scale: 'Seconds from the doctor pressing Call next until the number appears on the hall screen.',
  meter: 'Timestamps logged by the server and the screen client during 1,000 calls of the load test with 500 concurrent users; 95th percentile.',
  goal: '2 seconds',
  stretch: '1 second',
  wish: '0.5 seconds',
  defined: 'Hall screen: the 55-inch display in each waiting hall.',
};

